<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'RequestDokumenCollection' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 truncate font-medium text-ui-ink-gray-900"
					>Tambah Request Dokumen Collection</span
				>
			</div>
		</div>

		<!-- ============ FORM ============ -->
		<div class="flex flex-1 flex-col">
			<div class="app-container-narrow px-4 py-5 text-base md:px-6">
				<pre
					v-if="saveError"
					class="mb-4 rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm text-ui-ink-red-700 whitespace-pre-wrap"
					>{{ saveError }}</pre
				>

				<section
					class="space-y-4 rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<!-- Jenis Dokumen (segmented) -->
					<div>
						<label class="mb-1.5 block text-base font-medium text-ui-ink-gray-500">
							Jenis Dokumen <span class="text-ui-ink-red-500">*</span>
						</label>
						<div class="grid grid-cols-2 gap-2">
							<button
								v-for="j in JENIS_LIST"
								:key="j"
								type="button"
								class="rounded-xl border px-3 py-3 text-sm font-semibold transition"
								:class="
									form.jenis_dokumen === j
										? 'border-primary bg-primary/5 text-primary'
										: 'border-ui-line-gray-200 text-ui-ink-gray-700 hover:border-primary/60'
								"
								@click="selectJenis(j)"
							>
								{{ j }}
							</button>
						</div>
					</div>

					<!-- Cabang berlaku untuk TTS dan BSTK -->
					<div>
						<label class="mb-1.5 block text-base font-medium text-ui-ink-gray-500">
							Cabang <span class="text-ui-ink-red-500">*</span>
						</label>
						<div class="grid grid-cols-2 gap-2">
							<button
								v-for="c in CABANG_LIST"
								:key="c"
								type="button"
								class="rounded-xl border px-3 py-3 text-sm font-semibold transition"
								:class="
									form.cabang_collection === c
										? 'border-primary bg-primary/5 text-primary'
										: 'border-ui-line-gray-200 text-ui-ink-gray-700 hover:border-primary/60'
								"
								@click="form.cabang_collection = c"
							>
								{{ c }}
							</button>
						</div>
					</div>

					<!-- Tanggal Request -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Tanggal Request <span class="text-ui-ink-red-500">*</span>
						</label>
						<input v-model="form.tanggal" type="date" :class="inputClass" />
					</div>

					<!-- Jumlah Buku -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Jumlah Buku <span class="text-ui-ink-red-500">*</span>
						</label>
						<input
							v-model.number="form.jumlah_buku"
							type="number"
							min="1"
							inputmode="numeric"
							placeholder="0"
							:class="inputClass"
						/>
						<p class="mt-1 text-xs text-ui-ink-gray-400">1 Buku = 50 lembar/nomor dokumen.</p>
					</div>

					<!-- Nomor Awal (TTS) -->
					<div v-if="form.jenis_dokumen === 'TTS'">
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Nomor Awal <span class="text-ui-ink-red-500">*</span>
						</label>
						<input
							v-model="form.nomor_awal"
							type="text"
							inputmode="numeric"
							maxlength="5"
							placeholder="00001"
							:class="inputClass"
							@input="onNomorAwalInput"
						/>
					</div>

					<!-- Preview terhitung (read-only): Jumlah Nomor & Nomor Akhir -->
					<div class="grid grid-cols-2 gap-3 rounded-xl bg-ui-surface-gray-50 px-3 py-3">
						<div class="min-w-0">
							<p class="text-xs text-ui-ink-gray-400">Jumlah Lembar / Nomor</p>
							<p class="mt-0.5 text-sm font-bold text-ui-ink-gray-900">{{ jumlahNomor }}</p>
						</div>
						<div v-if="form.jenis_dokumen === 'TTS'" class="min-w-0 text-right">
							<p class="text-xs text-ui-ink-gray-400">Nomor Akhir</p>
							<p class="mt-0.5 text-sm font-bold text-ui-ink-gray-900">
								{{ nomorAkhir || '—' }}
							</p>
						</div>
					</div>

					<!-- Catatan (opsional) -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500"
							>Catatan</label
						>
						<textarea
							v-model="form.catatan"
							rows="3"
							placeholder="Catatan tambahan (opsional)"
							:class="[inputClass, 'resize-none']"
						/>
					</div>
				</section>
			</div>
		</div>

		<!-- ============ ACTION BAR ============ -->
		<div
			class="sticky bottom-0 z-20 flex gap-2 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<RouterLink
				:to="{ name: 'RequestDokumenCollection' }"
				class="flex flex-1 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface py-2.5 text-sm font-medium text-ui-ink-gray-700"
			>
				Cancel
			</RouterLink>
			<button
				type="button"
				:disabled="saving"
				class="flex flex-1 items-center justify-center rounded-lg bg-primary py-2.5 text-sm font-medium text-ui-onPrimary transition hover:opacity-90 disabled:opacity-50"
				@click="submit"
			>
				{{ saving ? 'Menyimpan…' : 'Save' }}
			</button>
		</div>
	</div>
</template>

<script setup>
import { computed, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'

const router = useRouter()
const DOCTYPE = 'Request Dokumen Collection'

const JENIS_LIST = ['TTS', 'BSTK']
const CABANG_LIST = ['BTM', 'TPI']
const LEMBAR_PER_BUKU = 50

function today() {
	const d = new Date()
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
		d.getDate()
	).padStart(2, '0')}`
}

const form = reactive({
	jenis_dokumen: 'TTS',
	cabang_collection: '',
	tanggal: today(),
	jumlah_buku: null,
	nomor_awal: '',
	catatan: '',
})
const saving = ref(false)
const saveError = ref('')

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// ---- Preview terhitung (meniru recompute() desk) ---------------------------
// jumlah_nomor = jumlah_buku × 50; nomor_akhir = nomor_awal + jumlah_nomor − 1
// (5 digit, hanya TTS). Server tetap sumber kebenaran saat insert.
const jumlahNomor = computed(() => (Number(form.jumlah_buku) || 0) * LEMBAR_PER_BUKU)
const nomorAkhir = computed(() => {
	const raw = String(form.nomor_awal || '').trim()
	const jumlah = jumlahNomor.value
	if (form.jenis_dokumen !== 'TTS' || !/^\d{1,5}$/.test(raw) || jumlah <= 0) return ''
	const end = parseInt(raw, 10) + jumlah - 1
	return end <= 99999 ? String(end).padStart(5, '0') : ''
})

function selectJenis(j) {
	form.jenis_dokumen = j
	saveError.value = ''
	// Nomor awal hanya berlaku untuk TTS.
	if (j !== 'TTS') form.nomor_awal = ''
}
// Batasi input Nomor Awal ke digit (maks 5).
function onNomorAwalInput(e) {
	const v = String(e.target.value || '')
		.replace(/\D/g, '')
		.slice(0, 5)
	form.nomor_awal = v
}

// ---- Simpan ----------------------------------------------------------------
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

function validate() {
	const missing = []
	if (!form.jenis_dokumen) missing.push('Jenis Dokumen')
	if (!form.tanggal) missing.push('Tanggal Request')
	if (!form.jumlah_buku || Number(form.jumlah_buku) <= 0) missing.push('Jumlah Buku (> 0)')
	if (!form.cabang_collection) missing.push('Cabang')
	if (form.jenis_dokumen === 'TTS') {
		if (!form.nomor_awal) missing.push('Nomor Awal')
		else if (!/^\d{1,5}$/.test(form.nomor_awal)) missing.push('Nomor Awal (1–5 digit)')
	}
	return missing
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi: ${missing.join(', ')}`
		notifyError(saveError.value, 'Data belum lengkap')
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	// Cek batas nomor untuk TTS (server juga memvalidasi ulang).
	if (form.jenis_dokumen === 'TTS' && !nomorAkhir.value) {
		saveError.value = 'Range nomor melebihi 5 digit (maksimal 99999).'
		notifyError(saveError.value, 'Nomor tidak valid')
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		// jumlah_nomor, nomor_akhir, requested_by & status diisi server (validate).
		const doc = {
			doctype: DOCTYPE,
			jenis_dokumen: form.jenis_dokumen,
			tanggal: form.tanggal,
			jumlah_buku: form.jumlah_buku,
			cabang_collection: form.cabang_collection,
			catatan: form.catatan,
		}
		if (form.jenis_dokumen === 'TTS') doc.nomor_awal = form.nomor_awal
		const res = await fetch('/api/method/frappe.client.insert', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		notifySuccess('Request Dokumen Collection berhasil dibuat.')
		const name = json.message?.name
		if (name) router.push({ name: 'RequestDokumenCollectionDetail', params: { name } })
		else router.push({ name: 'RequestDokumenCollection' })
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
	}
}
</script>
